import{H as e,Q as t,ht as n,nt as r,tt as i}from"./chunks/framework.qcK96eCy.js";import"./chunks/assets.CN5ja4nF.js";var a=JSON.parse(`{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"mealie-mcp","text":"A curated, safe view of your Mealie instance for an AI model","tagline":"Search and cook from your recipes, import new ones, plan meals and build shopping lists — through 52 tools chosen so the common tasks are one call and the dangerous surface is out of reach.","actions":[{"theme":"brand","text":"Get started","link":"/guide/getting-started"},{"theme":"alt","text":"Tools reference","link":"/reference/tools"},{"theme":"alt","text":"GitHub","link":"https://github.com/ni-c/mealie-mcp"}]},"features":[{"title":"52 curated tools","details":"Mealie's REST API has 259 operations; this server exposes the ones a model should reach, so the common tasks are one call — search, read and import recipes, keep tags and categories tidy, plan meals, build shopping lists, manage cookbooks, ratings, comments and share links."},{"title":"The dangerous surface is unreachable","details":"No admin routes, no token minting, no webhooks or outbound-HTTP triggers — and no PUT-replace, which silently drops recipe fields. update_recipe uses PATCH, so only the fields you name change."},{"title":"A menu is not a plate","details":"MEALIE_READ_ONLY=true registers the read tools and nothing else. MEALIE_ALLOW_TOOLS cuts finer — essential for a curated eight, your own comma-separated list, or a whole family with list_* — and MEALIE_DENY_TOOLS subtracts. Whatever is filtered out does not exist on the protocol rather than failing when called, and a name that matches no tool stops the server at startup instead of quietly going missing."},{"title":"Safe by default","details":"The eleven irreversible tools ask a person first, through MCP elicitation — a dialog the model cannot answer on its behalf, falling back to a server-issued token bound to the exact target where the client cannot show one. Upstream content is marked untrusted, and read-only mode simply does not register the write tools."}]},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":1788380633000}`),o={name:`index.md`};function s(e,a,o,s,c,l){return n(),i(`div`,null,[...a[0]||=[t(`figure`,{class:`diagram`},[t(`svg`,{viewBox:`0 0 720 268`,role:`img`,"aria-labelledby":`arch-title arch-desc`},[t(`title`,{id:`arch-title`},`mealie-mcp architecture`),t(`desc`,{id:`arch-desc`},`An MCP client talks to mealie-mcp over stdio; mealie-mcp calls the Mealie REST API over HTTPS. Mealie itself fetches recipe websites server-side, which is why the URL guard refuses its own loopback and link-local range.`),t(`defs`,null,[t(`marker`,{id:`arch-arrow`,markerWidth:`9`,markerHeight:`9`,refX:`7`,refY:`3`,orient:`auto`},[t(`path`,{d:`M0,0 L7,3 L0,6 z`})]),t(`marker`,{id:`arch-arrow-accent`,class:`accent`,markerWidth:`9`,markerHeight:`9`,refX:`7`,refY:`3`,orient:`auto`},[t(`path`,{d:`M0,0 L7,3 L0,6 z`})])]),t(`rect`,{class:`node`,x:`20`,y:`70`,width:`160`,height:`80`,rx:`10`}),t(`text`,{class:`label-title`,x:`100`,y:`103`,"text-anchor":`middle`},`MCP client`),t(`text`,{class:`label-muted`,x:`100`,y:`123`,"text-anchor":`middle`},`Claude, Codex, …`),t(`rect`,{class:`node-accent`,x:`280`,y:`55`,width:`170`,height:`110`,rx:`10`}),t(`text`,{class:`label-title`,x:`365`,y:`87`,"text-anchor":`middle`},`mealie-mcp`),t(`text`,{class:`label-muted`,x:`365`,y:`107`,"text-anchor":`middle`},`52 tools`),t(`text`,{class:`label-muted`,x:`365`,y:`125`,"text-anchor":`middle`},`asks a person`),t(`text`,{class:`label-muted`,x:`365`,y:`143`,"text-anchor":`middle`},`read-only mode`),t(`rect`,{class:`node`,x:`550`,y:`70`,width:`150`,height:`80`,rx:`10`}),t(`text`,{class:`label-title`,x:`625`,y:`103`,"text-anchor":`middle`},`Mealie`),t(`text`,{class:`label-muted`,x:`625`,y:`123`,"text-anchor":`middle`},`recipes · plans · lists`),t(`path`,{class:`edge-accent`,d:`M180,110 L272,110`,"marker-end":`url(#arch-arrow-accent)`}),t(`text`,{class:`label-mono`,x:`226`,y:`98`,"text-anchor":`middle`},`stdio`),t(`path`,{class:`edge-accent`,d:`M450,110 L542,110`,"marker-end":`url(#arch-arrow-accent)`}),t(`text`,{class:`label-mono`,x:`496`,y:`98`,"text-anchor":`middle`},`HTTPS`),t(`text`,{class:`label-muted`,x:`496`,y:`130`,"text-anchor":`middle`},`/api/*`),t(`path`,{class:`edge edge-dashed`,d:`M625,150 L625,196`,"marker-end":`url(#arch-arrow)`}),t(`text`,{class:`label-muted`,x:`610`,y:`216`,"text-anchor":`middle`},`scrapes recipe sites server-side —`),t(`text`,{class:`label-muted`,x:`610`,y:`232`,"text-anchor":`middle`},`URL guard refuses loopback + link-local`)]),t(`figcaption`,null,`One stdio server between the MCP client and the Mealie REST API — destructive calls put to a person first, upstream content marked untrusted.`)],-1),r(`<h2 id="see-it-in-action" tabindex="-1">See it in action <a class="header-anchor" href="#see-it-in-action" aria-label="Permalink to “See it in action”">​</a></h2><p><img src="/demo.gif" alt="Demo of mealie-mcp in Claude Code" width="1200" height="640"></p><h2 id="running-it-elsewhere" tabindex="-1">Running it elsewhere <a class="header-anchor" href="#running-it-elsewhere" aria-label="Permalink to “Running it elsewhere”">​</a></h2><p>A client that cannot spawn a local process — ChatGPT connectors, Claude on the web, Cursor, LibreChat — cannot start mealie-mcp the way Claude Code does. <a href="https://mcp-hub.ni-c.de" target="_blank" rel="noreferrer">mcp-hub</a> is the bridge: one container serves many stdio MCP servers over Streamable HTTP, with an OAuth 2.1 login behind a single password and long-lived tokens for the clients that cannot do OAuth. Its <code>/hub</code> endpoint puts every server behind six meta-tools, so one connector reaches all of them without N×tool schemas in the model&#39;s context, and it speaks both protocol revisions — a question this server asks travels through it to the person at the far end instead of ending at the gateway.</p><p>Its configuration is Claude Code&#39;s <code>mcpServers</code> format, so the entry you already have is the entry it takes: <a href="/guide/clients#through-mcp-hub">Through mcp-hub</a>.</p>`,5)]])}var c=e(o,[[`render`,s]]);export{a as __pageData,c as default};